js.text:

function grid$chcall(f){
  this.constructor(f);
}
grid$chcall.prototype = new DirEvent();
grid$chcall.prototype.afterInit = function(renderType){
  var p = this._dir;
}
grid$chcall.prototype.beforeButtonGridClick = function(id){
  if (id == 'register') {
    var p = this._dir, g = p.grid(), r = p.curr("r");
    if (r == null || r < 0) return;

    var m = new Memvars(), vc = g.data.val(r, 'id');   
    register(this, vc);
    return false;
  }
  return true
}


function register(o, id) {
  $.invoke('RegisterDepositCode', { id: id }, this, 30000
    , function (result) {
		console.log(result);
      if (result) {
        if(result) $.alert(result);
      }
    }, function (event) {} );
}

css.text:

		.table-bottom{
			left: 0px!important;
			height: calc(100% - 77px);
			top: 0px;
			position: relative;
			margin-top: 27px;
			clear: both;
			border-bottom: 1px solid #ddd;
		}
		#content .dir{
			position: relative !important;
			height: 100%;
		}

		@media only screen and (max-width: 767px) {
		  .table-bottom{
			margin-top: 42px;
			height: calc(100% - 92px);
		  }
		}
    .toolbar-register{
      background-repeat: no-repeat;
      background-image: url('data:image/gif;base64,');
   }
